const grpc = require('@grpc/grpc-js');
const { telemetryRedis } = require('../redis');
const { extractGrpcUser } = require('../auth');
const { db } = require('../db');

async function streamDeviceTelemetry(call) {
  const caller = extractGrpcUser(call.metadata);
  if (!caller) {
    call.emit('error', { code: grpc.status.UNAUTHENTICATED, message: 'Unauthorized' });
    return;
  }

  const sensorId = call.request.sensorId;
  const permission = await db.query(
    'SELECT id FROM facility_sensors WHERE sensor_id = $1 AND facility_id = $2',
    [sensorId, caller.facilityId]
  );
  if (permission.rowCount === 0) {
    call.emit('error', { code: grpc.status.PERMISSION_DENIED, message: 'Access denied to sensor feed' });
    return;
  }

  const sub = telemetryRedis.duplicate();
  sub.subscribe(`sensors:${sensorId}:feed`);

  sub.on('message', (channel, message) => {
    call.write(JSON.parse(message));
  });

  call.on('cancelled', () => {
    sub.unsubscribe();
    sub.quit();
  });
}
